const username = $json.body.erp_username;
const password = $json.body.erp_password;

// Open ERP login page
await $page.goto(
  'https://meta-digitrading.lhike-erp.com/home',
  {
    waitUntil: 'networkidle2',
    timeout: 60000
  }
);

// Wait for login form
await $page.waitForSelector('input[name="txtusername"]', {
  timeout: 30000
});

// Fill credentials
await $page.type('input[name="txtusername"]', username, {
  delay: 50
});

await $page.type('input[name="txtpass"]', password, {
  delay: 50
});

// Submit login form
await Promise.all([
  $page.click('button[type="submit"]'),
  $page.waitForNavigation({
    waitUntil: 'networkidle2',
    timeout: 60000
  }).catch(() => null)
]);

// Check for login error
const loginError = await $page.$('.alert-danger');

if (loginError) {
  const errorText = await $page.evaluate(
    el => el.textContent.trim(),
    loginError
  );

  throw new Error(`Login failed: ${errorText}`);
}

// Optional: verify login succeeded
const currentUrl = $page.url();

if (currentUrl.includes('/login')) {
  throw new Error('Login may have failed. Still on login page.');
}

// Get cookies
const cookies = await $page.cookies();

return [
  {
    json: {
      success: true,
      currentUrl,
      cookies
    }
  }
];

const { cookies } = $json;
// set cookies
if (cookies && cookies.length) {
  await $page.setCookie(...cookies);
}
await $page.setViewport({ width: 1512, height: 982, deviceScaleFactor: 1 });

// goto unit code pages
await $page.goto('https://meta-digitrading.lhike-erp.com/codes', {
  waitUntil: 'networkidle2', timeout: 60000,
});

// wait to complete loading
await $page.waitForFunction(() => {
  const el = document.querySelector('#global-preloader');
  return !el || el.style.display === 'none';
}, { timeout: 60000 });
await new Promise(r => setTimeout(r, 5000));

async function extractTable() {
  return await $page.evaluate(() => {
    const table = document.querySelector('table.dataTable') || document.querySelector('table');
    if (!table) return [];

    const headers = Array.from(table.querySelectorAll('thead th')).map(th => {
      const clone = th.cloneNode(true);
      clone.querySelectorAll('select, input, textarea, button').forEach(n => n.remove());
      return clone.innerText.trim();
    });

    // pull the full, un-truncated text out of a cell
    const cellText = (td) => {
      // 1) strip the "more"/"less" toggle links so they don't pollute the text
      const clone = td.cloneNode(true);
      clone.querySelectorAll('a, button').forEach(n => {
        if (/^\s*(\.{2,3}\s*)?(more|less|read more|show more)\s*$/i.test(n.innerText)) n.remove();
      });

      // 2) prefer an explicit full-text source if the page provides one
      const full =
        td.querySelector('[data-full], [data-fulltext], [data-text], [data-original-title]');
      if (full) {
        const v = full.getAttribute('data-full')
               || full.getAttribute('data-fulltext')
               || full.getAttribute('data-text')
               || full.getAttribute('data-original-title');
        if (v && v.trim()) return v.trim();
      }

      // 3) a title attribute often holds the complete value
      const titled = td.querySelector('[title]') || (td.getAttribute('title') ? td : null);
      if (titled) {
        const v = titled.getAttribute('title');
        if (v && v.trim()) return v.trim();
      }

      // 4) a hidden span holding the full text (common in read-more widgets)
      const hidden = td.querySelector('.full, .full-text, .more-text, span[style*="display:none"], span[style*="display: none"]');
      if (hidden && hidden.textContent.trim()) return hidden.textContent.trim();

      // 5) fallback: clean visible text — drop trailing ellipsis + "more"
      return clone.innerText
        .replace(/\s*\.{2,3}\s*more\s*$/i, '')
        .replace(/\s*more\s*$/i, '')
        .trim();
    };

    return Array.from(table.querySelectorAll('tbody tr')).map(tr => {
      const cells = Array.from(tr.querySelectorAll('td'));
      if (!cells.length) return null;
      const obj = {};
      cells.forEach((td, i) => { obj[headers[i] || `col_${i}`] = cellText(td); });

      const viewLink = tr.querySelector('a[href*="/view/"], a[href*="/edit/"]');
      if (viewLink) {
        const m = viewLink.getAttribute('href').match(/\/(?:view|edit)\/(\d+)/);
        if (m) obj.row_id = m[1];
      }
      return obj;
    }).filter(Boolean);
  });
}

function normalize(row) {
  const out = {};
  for (const [rawKey, value] of Object.entries(row)) {
    const key = (rawKey || '').trim();
    if (!key) continue;
    if (/^col_\d+$/i.test(key)) continue;
    if (/[\n\r]/.test(key)) continue;
    if (/^(actions?|search)$/i.test(key)) continue;
    out[key] = value;
  }
  return out;
}

async function isNextDisabled() {
  return await $page.evaluate(() => {
    const nextLi = document.querySelector('li.next');
    return !nextLi || nextLi.classList.contains('disabled');
  });
}

async function tableInfo() {
  return await $page.evaluate(() =>
    (document.querySelector('.dataTables_info, [id$="_info"]') || {}).innerText?.trim() || ''
  );
}

async function waitProcessingDone() {
  await $page.waitForFunction(() => {
    const el = document.querySelector('#tblcodes_processing, [id$="_processing"]');
    return !el || el.style.display === 'none' || el.offsetParent === null;
  }, { timeout: 60000 });
}

// bump page length to 100 to reduce pagination round-trips
const lengthSel = await $page.$('select[name$="_length"]');
if (lengthSel) {
  await $page.select('select[name$="_length"]', '100');
  await $page.waitForNetworkIdle({ idleTime: 800, timeout: 60000 });
}

await $page.waitForSelector('table');

const all = [];
const seen = new Set();
while (true) {
  await waitProcessingDone();

  const pageRows = await extractTable();
  for (const raw of pageRows) {
    const key = JSON.stringify(raw);
    if (!seen.has(key)) { seen.add(key); all.push(normalize(raw)); }
  }

  if (await isNextDisabled()) break;

  const prevInfo = await tableInfo();

  // click inside the page (avoids viewport / overlay issues)
  const clicked = await $page.evaluate(() => {
    const a = document.querySelector('li.next:not(.disabled) a, a.paginate_button.next:not(.disabled)');
    if (a) { a.click(); return true; }
    return false;
  });
  if (!clicked) break;

  try {
    // wait for the page to actually advance (info text changes deterministically)
    await $page.waitForFunction((prev) => {
      const info = document.querySelector('.dataTables_info, [id$="_info"]');
      const now = info ? info.innerText.trim() : '';
      return now && now !== prev;
    }, { timeout: 60000 }, prevInfo);
  } catch (e) {
    // pagination stalled — stop instead of throwing, keep what we have
    break;
  }
}

return all.map(r => ({ json: r }));

