function parseItems(s) {
  return s
    .split(/,\s*(?![^()]*\))/)              // split items, keep parens intact
    .map((i) => i.trim())
    .filter(Boolean)
    .map((item) => {
      const m = item.match(/^(.*?)\s*\(([^)]*)\)\s*$/);
      return {
        sku: (m ? m[1] : item).trim(),       // item name before the ()
        quantity: m ? m[2].split(",").length : 1, // how many values inside ()
      };
    });
}

const result = $input.all().map(row => ({
  json: {
    row_id: row.json.row_id,
    sku: row.json.SKU,
    unit_code: row.json.Code,
    total_amount: row.json["Total Amount"],
    items: parseItems(row.json["Items"])
  }
}));

return result;
